insert into public.app_users(id,privy_user_id,verified_email)select('e9760000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'evidence-upgrade-'||n,'evidence-upgrade-'||n||'@example.test'from generate_series(1,3)n;
insert into public.group_pages(id,kind,name)values('e9760000-0000-4000-8000-000000000004','hobby','Existing activity upgrade fixture');
insert into public.group_memberships(page_id,app_user_id,role)select'e9760000-0000-4000-8000-000000000004'::uuid,('e9760000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case n when 1 then'owner'else'member'end from generate_series(1,3)n;
insert into public.group_missions(id,page_id,title,instructions,state)select('e9760000-0000-4000-8000-'||lpad((10+n)::text,12,'0'))::uuid,'e9760000-0000-4000-8000-000000000004','Existing mission '||n,'Existing instructions','published'from generate_series(1,3)n;
insert into public.group_mission_submissions(id,mission_id,app_user_id,body,status,reason,reviewed_by,reviewed_at,created_at)select('e9760000-0000-4000-8000-'||lpad((20+n)::text,12,'0'))::uuid,('e9760000-0000-4000-8000-'||lpad((10+n)::text,12,'0'))::uuid,'e9760000-0000-4000-8000-000000000002',E'기존 원문 그대로\nOriginal body '||n,case n when 1 then'pending'when 2 then'rejected'else'completed'end,case when n=2 then'기존 반려 사유'end,case when n>1 then'e9760000-0000-4000-8000-000000000001'::uuid end,case when n>1 then'2026-10-11T10:00:00Z'::timestamptz end,'2026-10-10T09:00:00Z'::timestamptz from generate_series(1,3)n;
insert into public.group_events(id,page_id,title,description,starts_at,ends_at,opens_at,closes_at,location,state,created_by)values('e9760000-0000-4000-8000-000000000030','e9760000-0000-4000-8000-000000000004','Existing ended event','Original event','2026-10-10T09:00:00Z','2026-10-10T12:00:00Z','2026-10-01T00:00:00Z','2026-10-09T23:00:00Z','Seoul','ended','e9760000-0000-4000-8000-000000000001');
insert into public.group_event_registrations(id,event_id,app_user_id,status,checked_in_at,review_body,reviewed_at,created_at)select('e9760000-0000-4000-8000-'||lpad((30+n)::text,12,'0'))::uuid,'e9760000-0000-4000-8000-000000000030',('e9760000-0000-4000-8000-'||lpad((n+1)::text,12,'0'))::uuid,'confirmed','2026-10-10T09:30:00Z',case when n=1 then E'기존 행사 후기\nOriginal review'end,case when n=1 then'2026-10-11T11:00:00Z'::timestamptz end,'2026-10-09T10:00:00Z'::timestamptz from generate_series(1,2)n;
insert into public.activity_evidence_upgrade_expected select'mission',id,to_jsonb(s)from public.group_mission_submissions s where id::text like'e9760000-%';
insert into public.activity_evidence_upgrade_expected select'event',id,to_jsonb(r)from public.group_event_registrations r where id::text like'e9760000-%';
